-- ===== 8. 自检SQL =====
-- 1. Code唯一
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: Code all unique' ELSE 'FAIL' END AS Check_SupplierCode FROM (SELECT Code FROM Base_Supplier WHERE IsDeleted=0 GROUP BY Code HAVING COUNT(*)>1)_;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: Customer Code unique' ELSE 'FAIL' END FROM (SELECT Code FROM Base_Customer WHERE IsDeleted=0 GROUP BY Code HAVING COUNT(*)>1)_;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: Category Code unique' ELSE 'FAIL' END FROM (SELECT Code FROM Base_Category WHERE IsDeleted=0 GROUP BY Code HAVING COUNT(*)>1)_;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: Product Code unique' ELSE 'FAIL' END FROM (SELECT Code FROM Base_Product WHERE IsDeleted=0 GROUP BY Code HAVING COUNT(*)>1)_;
-- 2. 库存无负
SELECT CASE WHEN MIN(Quantity)>=0 AND MIN(Quantity-LockQty)>=0 THEN 'PASS: Stock non-negative' ELSE 'FAIL' END FROM Base_ProductStock WHERE IsDeleted=0;
-- 3. 信用不超限
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: Credit not exceeded' ELSE 'FAIL' END FROM Base_Customer WHERE UsedCredit>CreditLimit AND IsDeleted=0;
-- 4. UQ_Stock无冲突
SELECT CASE WHEN COUNT(*)=COUNT(DISTINCT CONCAT(ProductId,'-',WarehouseId)) THEN 'PASS: UQ_Stock OK' ELSE 'FAIL' END FROM Base_ProductStock WHERE IsDeleted=0;
-- 5. UQ_CustomerPrice无冲突
SELECT CASE WHEN COUNT(*)=COUNT(DISTINCT CONCAT(CustomerId,'-',ProductId)) THEN 'PASS: UQ_CustPrice OK' ELSE 'FAIL' END FROM Base_CustomerPrice WHERE IsDeleted=0;
-- 6. 分类树完整性
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: Category tree OK' ELSE 'FAIL' END FROM Base_Category c1 LEFT JOIN Base_Category c2 ON c1.ParentId=c2.Id WHERE c1.ParentId IS NOT NULL AND c2.Id IS NULL AND c1.IsDeleted=0;
-- 7. ProductCat有效
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: All ProdCat valid' ELSE 'FAIL' END FROM Base_Product p LEFT JOIN Base_Category c ON p.CategoryId=c.Id WHERE p.IsDeleted=0 AND c.Id IS NULL;
-- 8. IsDefault唯一
SELECT CASE WHEN COUNT(*)=1 AND MAX(CAST(IsDefault AS INT))=1 THEN 'PASS: DefaultWarehouse=1' ELSE 'FAIL' END FROM Base_Warehouse WHERE IsDefault=1 AND IsDeleted=0;
-- 9. 预警产品统计
SELECT 'INFO' AS Check9, COUNT(*) AS LowStockCount FROM Base_ProductStock WHERE Quantity <= 15 AND IsDeleted=0;

COMMIT TRANSACTION;
